-- Bornes kilométriques des autoroutes wallonnes (source : SPW, réseau routier
-- régional). Sert à géolocaliser une adresse d'intervention "A27 BK22.3" que
-- Google ne sait pas géocoder → coordonnées → calcul du montant débloqué.
--
-- CUMULEE en mètres (km0=0, km1000=1km...). Résolution : on encadre la borne
-- demandée par la borne juste en dessous / au-dessus et on interpole.
-- Pré-chargé (A26/A27 + axes voisins) pour une résolution instantanée, sans
-- dépendre du service SPW au moment de l'intervention. Refresh via
-- /api/admin/highways/sync (superadmin).

create table if not exists public.highway_bornes_km (
  id          bigint generated always as identity primary key,
  highway_ref text    not null,
  cumulee_m   integer not null,
  lat         double precision not null,
  lng         double precision not null,
  updated_at  timestamptz not null default now(),
  unique (highway_ref, cumulee_m)
);

create index if not exists idx_highway_bornes_ref_cum
  on public.highway_bornes_km (highway_ref, cumulee_m);

-- Table serveur-only (lue par le résolveur côté serveur via service_role).
alter table public.highway_bornes_km enable row level security;
grant all on public.highway_bornes_km to service_role;

-- ── Seed initial (SPW, capté le 2026-07-03) ────────────────────────────────
on conflict (highway_ref, cumulee_m) do update
  set lat = excluded.lat, lng = excluded.lng, updated_at = now();

notify pgrst, 'reload schema';
